SELECT 'batch_029_78334fe1_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-04afa76593a947bab6e7aa9ab1fac848','sm-a04802ee79434c569c4a8037334fffe9','sm-aea8f18fd18a48d29d2a9b8e6c9cbfdc','sm-upload-0223d040-b1c','sm-upload-04789844-9c6','sm-upload-096c103b-c28','sm-upload-139421cf-b09','sm-upload-3ccc4425-662','sm-upload-5028ec56-8ea','sm-upload-558f35c9-d77') AND album_id='al-f79d077d5e583272b3cc93b078334fe1') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-04afa76593a947bab6e7aa9ab1fac848','sm-a04802ee79434c569c4a8037334fffe9','sm-aea8f18fd18a48d29d2a9b8e6c9cbfdc','sm-upload-0223d040-b1c','sm-upload-04789844-9c6','sm-upload-096c103b-c28','sm-upload-139421cf-b09','sm-upload-3ccc4425-662','sm-upload-5028ec56-8ea','sm-upload-558f35c9-d77') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-f79d077d5e583272b3cc93b078334fe1' AND name='实力至上-奇怪雷子QGRay') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-f79d077d5e583272b3cc93b078334fe1') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-f79d077d5e583272b3cc93b078334fe1') AS calculated_size;
